+/// The stations the bar spans: the model's own, widened by the setup
+/// stock's ends where they read.
+pub fn bar_span(d: (f64, f64), stock: Option<super::stock::StockEnv>) -> (f64, f64) {
+    let (mut lo, mut hi) = d;
+    if let Some(e) = stock {
+        if e.s_bot.is_finite() {
+            lo = lo.min(e.s_bot);
+        }
