+    assert!(part_kerf_refusal(&part, &plunge_at(&f, -71.5), 0.0, -70.0, TOL).is_some());
+    assert!(part_kerf_refusal(&[], &plunge_at(&f, -71.5), W, -70.0, TOL).is_some());
+}

